package org.example.learningprojectserver.entities;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

import java.time.LocalDateTime;

/**
 * A question-answer card written by a student (by hand or generated by the AI from a photo or a
 * summary). When {@code classRoomId} is set the card is shared with that class, and classmates can
 * add it to their own deck. Each student's schedule for a card lives in {@link FlashcardReviewEntity}.
 */
@Entity
@Table(name = "flashcard",
        indexes = {
                @Index(name = "idx_flashcard_owner", columnList = "ownerUserId"),
                @Index(name = "idx_flashcard_class", columnList = "classRoomId")
        })
@Getter
@Setter
@NoArgsConstructor
public class FlashcardEntity {

    public static final String SOURCE_MANUAL = "MANUAL";
    public static final String SOURCE_AI_TEXT = "AI_TEXT";
    public static final String SOURCE_AI_IMAGE = "AI_IMAGE";

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String ownerUserId;

    /** The class the card is shared with; null for a private card. */
    private Long classRoomId;

    private String subject;
    private String topic;

    @Column(nullable = false, length = 500)
    private String front;

    @Column(nullable = false, length = 1000)
    private String back;

    /** MANUAL, AI_TEXT or AI_IMAGE. */
    @Column(nullable = false, length = 16)
    private String source;

    @Column(nullable = false)
    private LocalDateTime createdAt;
}
